const input = $json.body;

const errors = [];

if (!input) {
  errors.push("Missing request body");
}

if (typeof input?.content !== "string") {
  errors.push("content must be a string");
}

if (typeof input?.content === "string" && input.content.trim() === "") {
  errors.push("content cannot be empty");
}

if (typeof input?.filename !== "string" || input.filename.trim() === "") {
  errors.push("filename is required");
}

if (typeof input?.filepath !== "string" || input.filepath.trim() === "") {
  errors.push("filepath is required");
}

if (!Number.isFinite(input?.timestamp)) {
  errors.push("timestamp must be a number");
}

if (errors.length > 0) {
  return [
    {
      json: {
        valid: false,
        errors,
        source: "obsidian",
      },
    },
  ];
}

return [
  {
    json: {
      valid: true,
      source: "obsidian",
      note: {
        content: input.content,
        filename: input.filename,
        filepath: input.filepath,
        timestamp: input.timestamp,
        createdAt: input.createdAt,
        modifiedAt: input.modifiedAt,
        attachments: input.attachments ?? [],
      },
    },
  },
];

return [
  {
    json: {
      success: false,
      error: "Invalid Obsidian payload",
      details: $json.errors ?? [],
    },
  },
];

const note = $json.note;

return [
  {
    json: {
      source: "obsidian",

      note: {
        filename: note.filename,
        filepath: note.filepath,
        content: note.content,

        timestamps: {
          timestamp: note.timestamp,
          createdAt: note.createdAt,
          modifiedAt: note.modifiedAt,
        },

        attachments: note.attachments ?? [],
      },
    },
  },
];

const content = $json.content;

if (!content) {
  throw new Error("Gemini content is missing");
}

let text;

// Gemini response: content.parts[0].text
if (content.parts && content.parts[0]?.text) {
  text = content.parts[0].text;
}

// Fallback: content is already a string
else if (typeof content === "string") {
  text = content;
}

if (!text || !text.trim()) {
  throw new Error("Gemini returned an empty response");
}

text = text.trim();

// Remove accidental Markdown code fences
if (text.startsWith("```")) {
  text = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
}

let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error(
    `Invalid AI JSON: ${error.message}\nReceived: ${text}`
  );
}

// The AI contract requires exactly one JSON object
if (
  typeof parsed !== "object" ||
  parsed === null ||
  Array.isArray(parsed)
) {
  throw new Error(
    "AI output must be exactly one JSON object"
  );
}

return {
  json: parsed
};

const data = $json;

const requiredFields = [
  'summary',
  'category',
  'topics',
  'key_concepts',
  'actions',
  'tags'
];

const arrayFields = [
  'topics',
  'key_concepts',
  'actions',
  'tags'
];

const errors = [];

// Required fields
for (const field of requiredFields) {
  if (!(field in data)) {
    errors.push(`Missing field: ${field}`);
  }
}

// String fields
if ('summary' in data && typeof data.summary !== 'string') {
  errors.push('summary must be a string');
}

if ('category' in data && typeof data.category !== 'string') {
  errors.push('category must be a string');
}

// Array fields
for (const field of arrayFields) {
  if (field in data) {
    if (!Array.isArray(data[field])) {
      errors.push(`${field} must be an array`);
      continue;
    }

    // Every array element must be a string
    for (const item of data[field]) {
      if (typeof item !== 'string') {
        errors.push(`${field} must contain only strings`);
        break;
      }
    }
  }
}

// Tags must start with #
if (Array.isArray(data.tags)) {
  for (const tag of data.tags) {
    if (typeof tag === 'string' && !tag.startsWith('#')) {
      errors.push(`Invalid tag: "${tag}". Tags must start with #`);
    }
  }
}

const valid = errors.length === 0;

return [
  {
    json: {
      ...data,
      validation: {
        valid,
        errors
      }
    }
  }
];

return [
  {
    json: {
      success: false,
      stage: "AI_OUTPUT_VALIDATION",
      errors: $json.validation?.errors || [
        "Unknown AI output validation error"
      ]
    }
  }
];
